function renderAnalysisStatus(){const el=$('#analysisDataStatus');if(!el)return;const current=latestByStudent(allResponses,selectedAnalysisMonth);const enrollment=IeumEnrollment.summary(classSettings.students,current.keys(),selectedAnalysisMonth);const total=enrollment.total;const submitted=enrollment.submitted.length;const rate=total?Math.round(submitted/total*100):0;const monthlyRows=allResponses.filter(item=>monthOf(item)===selectedAnalysisMonth);const duplicateCount=Math.max(0,monthlyRows.length-submitted);const relationshipCount=enrollment.submitted.filter(student=>(payloadOf(current.get(Number(student.number))).relationships||[]).length).length;const relationshipRate=total?Math.round(relationshipCount/total*100):0;const relationshipReady=rate>=80&&relationshipCount>=Math.ceil(total*.8);const concernCounts={친구:0,공부:0,성적:0,등하교:0,가정:0};current.forEach(item=>{const text=String(payloadOf(item).studentState?.worryDetail||'');Object.keys(concernCounts).forEach(key=>{if(text.includes(key))concernCounts[key]++})});const concerns=Object.entries(concernCounts).filter(([,count])=>count).sort((a,b)=>b[1]-a[1]).map(([key,count])=>`${key} ${count}건`).join(' · ')||'분류된 공통 고민 없음';el.className=`notice ${relationshipReady?'safe':'warning'}`;el.innerHTML=`<span>${relationshipReady?'✓':'!'}</span><div><strong>${monthLabel(selectedAnalysisMonth)} 데이터 상태 · 제출 ${submitted}/${total}명 (${rate}%) · 관계 문항 ${relationshipCount}/${total}명 (${relationshipRate}%)</strong><p>학생별 최신 제출을 분석합니다${duplicateCount?` · 추가 제출 ${duplicateCount}건은 최신 응답으로 대체됨`:''}. 관계 구조 분석: <b>${relationshipReady?'참고 가능':'데이터 부족'}</b>${relationshipReady?'':' (제출·관계 문항 응답률 80% 이상 필요)'} · 공통 고민: ${escapeHTML(concerns)}</p></div>`}
