function renderSettings(){const {teacherName,schoolYear,grade,classNumber,classId,students}=classSettings;$('#teacherName').value=teacherName;$('#schoolYear').value=schoolYear;$('#grade').value=grade;$('#classNumber').value=classNumber;$('#classId').value=classId||'';$('#teacherSecret').value='';$('#rosterCount').textContent=`${students.length}명`;$('#rosterBody').innerHTML=students.map((student,index)=>`<tr><td><input type="number" min="1" max="99" value="${student.number}" data-student-number="${index}" aria-label="${index+1}번째 학생 번호"></td><td><input maxlength="20" value="${escapeHTML(student.name)}" data-student-name="${index}" aria-label="${index+1}번째 학생 이름"></td><td><button class="remove-student" type="button" data-remove-student="${index}" aria-label="${escapeHTML(student.name)} 삭제">삭제</button></td></tr>`).join('');resetYearEndCleanupControls();renderEnrollmentControls()}
function collectSettingsForm(){const students=$$('#rosterBody tr').map((row,index)=>({number:Number(row.querySelector('[data-student-number]').value),name:row.querySelector('[data-student-name]').value.trim(),studentId:classSettings.students[index]?.studentId||null,transferredOn:classSettings.students[index]?.transferredOn||null,accessCode:classSettings.students[index]?.accessCode||''})).filter(student=>student.name).sort((a,b)=>a.number-b.number);return{teacherName:$('#teacherName').value.trim(),schoolYear:Number($('#schoolYear').value),grade:Number($('#grade').value),classNumber:Number($('#classNumber').value),classId:$('#classId').value.trim(),teacherSecret:$('#teacherSecret').value.trim(),students}}
async function applySettings(){const next=collectSettingsForm();if(!getTeacherSession()){showToast('교사 로그인 필요');return false}if(!next.classId||!next.teacherName||!next.students.length){showToast('학급 ID, 교사 이름과 학생을 한 명 이상 입력해 주세요.');return false}try{await teacherRpc('teacher_update_class_context_auth',{p_class_id:next.classId,p_teacher_name:next.teacherName,p_school_year:next.schoolYear,p_grade:next.grade,p_class_number:next.classNumber});await teacherRpc('teacher_sync_roster_auth',{p_class_id:next.classId,p_students:next.students.map(({number,name,studentId})=>({number,name,studentId}))});classSettings={...classSettings,...next,teacherSecret:''};await loadTeacherContext();syncSignalNames();renderClassIdentity();renderSettings();renderStudents();renderParticipationLink();renderHomeSignals();renderClassTrend();renderAnalysis($('.filter-tabs .active')?.dataset.filter||'all');renderStudentDetailSelector();showToast('학급 정보와 명단을 DB에 저장했습니다.');return true}catch(error){showToast(`학급 설정 저장 실패: ${error.message}`);return false}}
