function applyAnalysisMonth() {
  ['#analysisMonth', '#surveyMonth'].forEach(id => {
    const selector = $(id);
    if (selector) selector.value = selectedAnalysisMonth;
  });

  signals = analyzeResponses(allResponses, selectedAnalysisMonth);
  renderResponses(allResponses);
  normalizeParticipationLabel();
  renderResponseManagement();
  renderAnalysisStatus();
  renderHomeSignals();
  renderClassTrend();
  renderClassResponseFlowMetrics();
  renderAdditionalResponses(currentAiAnalysis?.meta?.month===selectedAnalysisMonth?currentAiAnalysis.analysis:{});
  renderAnalysis($('.filter-tabs .active')?.dataset.filter || 'all');
  renderRelationshipsV2();
  renderRelationshipActions();
  renderStudentDetailSelector();
  renderStudentDetail();

  document.dispatchEvent(new CustomEvent('class-ieum:data-updated'));
  ensureAiAnalysis();
}

async function refreshResponses(showNotice = true) {
  if (!getTeacherSession()) {
    if (showNotice) $('#authDialog').showModal();
    return;
  }

  const isCurrentContext = captureTeacherContext();
  const version = ++responseRefreshVersion;
  const isCurrent = () => isCurrentContext() && version === responseRefreshVersion;
  try {
    const rows = await teacherRpc('teacher_get_responses_auth', {
      p_class_id: classSettings.classId
    });
    if (!isCurrent()) return;
    allResponses = rows.map(row => {
      const student = row.student_id && classSettings.students.find(
        item => item.studentId === row.student_id
      );
      return student
        ? {...row, student_number: student.number, student_name: student.name}
        : row;
    });

    await Promise.all([refreshGovernance(), refreshSignalReviews()]);
    if (!isCurrent()) return;
    updateMonthSelector();
    applyAnalysisMonth();
    if (showNotice) showToast('로그인 계정의 학생 설문 응답을 불러왔습니다.');
  } catch (error) {
    if (isCurrent()) showToast(`자료를 불러오지 못했습니다: ${error.message}`);
  }
}
function showToast(message){const el=$('#toast');el.textContent=String(message).replaceAll('AI 관찰 보조','AI 분석');el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)}
function handleAuthCallbackNotice(){const query=new URLSearchParams(location.search),fragment=new URLSearchParams(location.hash.replace(/^#/,'')),type=fragment.get('type')||query.get('type'),error=fragment.get('error_description')||query.get('error_description')||fragment.get('error')||query.get('error'),notice=$('#authCallbackNotice');if(!notice)return;if(error){notice.textContent=`이메일 인증에 실패했습니다. ${error.replaceAll('+',' ')}`;notice.className='auth-callback-notice error';notice.hidden=false}else if(type==='recovery'&&fragment.has('access_token')){setTeacherSession({access_token:fragment.get('access_token'),refresh_token:fragment.get('refresh_token'),expires_in:Number(fragment.get('expires_in')||0),token_type:fragment.get('token_type')||'bearer'});notice.textContent='본인 확인이 완료되었습니다. 새 비밀번호를 설정해 주세요.';notice.className='auth-callback-notice success';notice.hidden=false;openAuthDialog('recovery')}else if(type==='signup'||fragment.has('access_token')){notice.textContent='이메일 인증이 완료되었습니다. 가입한 이메일과 비밀번호로 로그인해 주세요.';notice.className='auth-callback-notice success';notice.hidden=false}else return;const clean=new URL(location.href);['type','error','error_code','error_description','code'].forEach(key=>clean.searchParams.delete(key));clean.hash='';history.replaceState(null,document.title,`${clean.pathname}${clean.search}`)}
const signalReviewStatuses={unreviewed:'확인 전',conversation_planned:'대화 예정',fact_checking:'사실 확인 중',support_connected:'지원 연결',no_issue:'특이사항 없음',closed:'종결'};
function signalKey(signal){return [selectedAnalysisMonth,signal.sourceResponseId||signal.submittedAt||'derived',signal.studentNumber||0,signal.type,signal.title].join('|')}
function signalReviewFor(signal){return signalReviews.find(item=>item.signal_key===signalKey(signal))}
async function refreshSignalReviews() {
  const isCurrent = captureTeacherContext();
  const reviews = await teacherRpc('teacher_get_signal_reviews_auth', {p_class_id: classSettings.classId});
  if (isCurrent()) signalReviews = reviews || [];
}
function renderSignalInbox(){const inbox=$('#signalReviewInbox');if(!inbox)return;const relevant=signals.filter(signal=>signal.type==='urgent'||signal.type==='week');const resolved=new Set(['support_connected','no_issue','closed']),today=new Date().toISOString().slice(0,10);const statusOf=signal=>signalReviewFor(signal)?.status||'unreviewed';const open=relevant.filter(signal=>!resolved.has(statusOf(signal))),overdue=open.filter(signal=>{const date=signalReviewFor(signal)?.follow_up_date;return date&&date<today});$('#signalReviewCount').textContent=`${open.length}건 확인 필요 · 전체 ${relevant.length}건`;$('#signalReviewUnreviewed').textContent=relevant.filter(signal=>statusOf(signal)==='unreviewed').length;$('#signalReviewInProgress').textContent=relevant.filter(signal=>['conversation_planned','fact_checking'].includes(statusOf(signal))).length;$('#signalReviewOverdue').textContent=overdue.length;$$('[data-signal-review-filter]').forEach(button=>button.classList.toggle('active',button.dataset.signalReviewFilter===signalReviewFilter));const visible=relevant.filter(signal=>signalReviewFilter==='all'||(signalReviewFilter==='open'&&!resolved.has(statusOf(signal)))||(signalReviewFilter==='done'&&resolved.has(statusOf(signal)))).sort((a,b)=>{const aReview=signalReviewFor(a)||{},bReview=signalReviewFor(b)||{};const aOverdue=aReview.follow_up_date&&aReview.follow_up_date<today,bOverdue=bReview.follow_up_date&&bReview.follow_up_date<today;return Number(bOverdue)-Number(aOverdue)||Number(b.type==='urgent')-Number(a.type==='urgent')});if(!visible.length){inbox.innerHTML=`<div class="signal-review-empty"><strong>${relevant.length?'선택한 상태의 신호가 없습니다.':'현재 확인할 안전 신호가 없습니다.'}</strong><p>${relevant.length?'다른 상태 필터를 선택해 주세요.':'선택한 달의 응답에서 담임 확인이 필요한 내용이 생기면 이곳에 표시됩니다.'}</p></div>`;return}inbox.innerHTML=visible.map(signal=>{const review=signalReviewFor(signal)||{},status=review.status||'unreviewed',isOverdue=review.follow_up_date&&review.follow_up_date<today&&!resolved.has(status);return`<article class="signal-review-card ${status==='unreviewed'?'unreviewed':''} ${isOverdue?'overdue':''}" data-signal-key="${escapeHTML(signalKey(signal))}"><header><div><span class="tag ${signal.type}">${escapeHTML(signal.tag)}</span><strong>${escapeHTML(signal.name)}</strong>${isOverdue?'<span class="tag urgent">기한 경과</span>':''}</div><small>${escapeHTML(monthLabel(selectedAnalysisMonth))}</small></header><h3>${escapeHTML(signal.title)}</h3><p>${escapeHTML(signal.summary)}</p><button class="evidence-button signal-source-button" type="button" data-review-evidence="${signal.id}">연결된 근거 확인</button><div class="signal-review-controls"><label><span>확인 상태</span><select data-signal-review-status>${Object.entries(signalReviewStatuses).map(([value,label])=>`<option value="${value}" ${value===status?'selected':''}>${label}</option>`).join('')}</select></label><label><span>후속 확인일</span><input type="date" data-signal-review-date value="${escapeHTML(review.follow_up_date||'')}"></label><label class="signal-review-note"><span>교사 메모</span><input data-signal-review-note maxlength="300" value="${escapeHTML(review.note||'')}" placeholder="확인할 장면이나 다음 조치"></label><button class="primary-button" type="button" data-save-signal-review="${signal.id}">상태 저장</button></div></article>`}).join('')}
function homeStudentLinks(numbers,kind){const rows=[...numbers].map(number=>classSettings.students.find(student=>Number(student.number)===Number(number))).filter(Boolean).sort((a,b)=>Number(a.number)-Number(b.number));return rows.length?rows.map(student=>`<button type="button" class="home-student-link ${kind}" data-open-student="${Number(student.number)}" aria-label="${escapeHTML(student.name)} 학생 살펴보기">${escapeHTML(student.name)}</button>`).join(''):'<span class="home-student-empty">해당 학생 없음</span>'}
function renderHomeSignals(){const urgentStudents=new Set(signals.filter(signal=>signal.type==='urgent'&&signal.studentNumber).map(signal=>Number(signal.studentNumber)));const observationStudents=new Set(signals.filter(signal=>signal.type!=='urgent'&&signal.studentNumber).map(signal=>Number(signal.studentNumber)));urgentStudents.forEach(number=>observationStudents.delete(number));const latest=latestByStudent(allResponses,selectedAnalysisMonth);const positive=[...latest.values()].filter(item=>{const peer=payloadOf(item).peerObservations||{};return peer.kind?.detail||peer.growth?.detail}).length;$('#homeUrgent').innerHTML=`${urgentStudents.size} <small>명</small>`;$('#homeWeek').innerHTML=`${observationStudents.size} <small>명</small>`;$('#homeUrgentStudents').innerHTML=homeStudentLinks(urgentStudents,'urgent');$('#homeWeekStudents').innerHTML=homeStudentLinks(observationStudents,'watch');$('#homePositive').innerHTML=`${positive} <small>건</small>`;renderSignalInbox()}
function classMonthlyTrend(responses){const byMonth=new Map();responses.filter(item=>!item.analysis_excluded).forEach(item=>{const month=monthOf(item),number=Number(item.student_number||payloadOf(item).studentNumber);if(!/^\d{4}-\d{2}$/.test(month)||!number)return;if(!byMonth.has(month))byMonth.set(month,new Map());const current=byMonth.get(month).get(number),time=new Date(item.submitted_at||payloadOf(item).submittedAt||0);if(!current||time>current.time)byMonth.get(month).set(number,{item,time})});return[...byMonth.entries()].sort(([a],[b])=>a.localeCompare(b)).slice(-6).map(([month,students])=>{const scores=[];students.forEach(({item})=>Object.values(payloadOf(item).selfRatings||{}).forEach(value=>{const score=Number(value?.score??value);if(score>=1&&score<=5)scores.push(score)}));return{month,participants:students.size,rate:IeumEnrollment.summary(classSettings.students,students.keys(),month).rate,average:scores.length?scores.reduce((sum,value)=>sum+value,0)/scores.length:null}})}
function renderClassTrend(){const chart=$('#classTrendChart'),confidence=$('#classTrendConfidence'),insight=$('#classTrendInsight');if(!chart||!confidence||!insight)return;const setInsightTone=tone=>insight.className=`insight trend-${tone}`;const trend=classMonthlyTrend(allResponses);if(!trend.length){setInsightTone('neutral');confidence.textContent='등록 자료 0건';chart.innerHTML='<p class="muted class-trend-empty">월별 설문 자료 없음</p>';insight.innerHTML='<span>ⓘ</span><p><strong>월별 비교 자료 없음</strong><br>미제출·분석 제외 응답 제외</p>';return}confidence.textContent=`최근 ${trend.length}개월 · ${trend.at(-1).rate}% 참여`;chart.innerHTML=`<div class="chart-line">${trend.map((row,index)=>`<span class="${index===trend.length-1?'current':''}" style="height:${row.average?Math.max(12,row.average/5*82):8}%"><b>${row.average?row.average.toFixed(1):'—'}</b><small>${row.participants}명</small></span>`).join('')}</div><div class="chart-labels">${trend.map(row=>`<span>${Number(row.month.slice(5))}월</span>`).join('')}</div>`;const latest=trend.at(-1),before=trend.at(-2);if(!before||latest.average===null||before.average===null){setInsightTone('neutral');insight.innerHTML=`<span>ⓘ</span><p><strong>${monthLabel(latest.month)} 실제 응답 ${latest.participants}명</strong><br>다음 달 응답 후 변화 비교</p>`;return}const delta=latest.average-before.average,steady=Math.abs(delta)<.05,direction=steady?'비슷합니다':delta>0?'높아졌습니다':'낮아졌습니다';setInsightTone(steady?'neutral':delta>0?'positive':'attention');insight.innerHTML=`<span>${steady?'→':delta>0?'↗':'↘'}</span><p><strong>학급 자기평가 평균이 지난달보다 ${Math.abs(delta).toFixed(1)}점 ${direction}</strong><br>${before.participants}명과 ${latest.participants}명의 실제 제출 자료를 비교했습니다. 참여 학생 구성이 다를 수 있어 관찰과 함께 해석하세요.</p>`}
function renderAnalysis(filter='all'){const container=$('#analysisCards');if(!container)return;const allGroups=groupedSignals();const counts={all:allGroups.length,urgent:allGroups.filter(group=>group.type==='urgent').length,watch:allGroups.filter(group=>group.type==='watch').length};$$('.filter-tabs button').forEach(button=>{const labels={all:'전체',urgent:'즉시 확인',watch:'지속 관찰'};button.textContent=`${labels[button.dataset.filter]} ${counts[button.dataset.filter]}`});const visible=groupedSignals(filter);container.innerHTML=visible.length?visible.map(group=>{const evidenceCount=group.items.reduce((sum,item)=>sum+item.evidence.length,0);return`<article class="analysis-card" data-type="${group.type}"><header><div><div class="analysis-card-tags"><span class="tag ${group.type}">${group.tag}</span><span class="change-badge">${escapeHTML(group.trend)}</span></div><h3>${escapeHTML(group.name)} · 통합 확인 카드</h3><div class="signal-summary">${group.items.map(item=>`<p><strong>▣ ${escapeHTML(item.title)}</strong><br>${escapeHTML(item.summary)}</p>`).join('')}</div>${group.protectiveFactors.length?`<div class="protective-factors"><strong>긍정적 보호요인</strong><p>${group.protectiveFactors.map(item=>`✓ ${escapeHTML(item)}`).join(' · ')}</p></div>`:''}</div></header><footer><span class="evidence-count">신호 ${group.items.length}개 · 근거 ${evidenceCount}개</span><button class="evidence-button" data-evidence-group="${group.ids.join(',')}">통합 근거와 관찰 제안</button></footer></article>`}).join(''):'<div class="panel"><p class="muted">선택한 조건에 해당하는 실제 응답 신호가 없습니다.</p></div>'}
function hasKoreanBatchim(value){const code=String(value||'').trim().charCodeAt(String(value||'').trim().length-1);return code>=0xac00&&code<=0xd7a3?(code-0xac00)%28:0}
function koreanParticleFor(value,particle){const jong=hasKoreanBatchim(value),has=jong>0,pairs={은:['은','는'],는:['은','는'],이:['이','가'],가:['이','가'],을:['을','를'],를:['을','를'],과:['과','와'],와:['과','와'],이나:['이나','나'],나:['이나','나'],이랑:['이랑','랑'],랑:['이랑','랑']};if(particle==='으로'||particle==='로')return!has||jong===8?'로':'으로';const pair=pairs[particle];return pair?(has?pair[0]:pair[1]):particle||''}
function escapeRegExp(value){return String(value).replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}
function replaceKoreanLabel(value,label,replacement){const pattern=new RegExp(`${escapeRegExp(label)}(으로|이나|이랑|은|는|이|가|을|를|과|와|로|나|랑)?`,'g');return String(value||'').replace(pattern,(match,particle)=>`${replacement}${koreanParticleFor(replacement,particle)}`)}
function teacherStudentName(number){return classSettings.students.find(student=>Number(student.number)===Number(number))?.name||'이전 명단 학생'}
function aiTeacherDisplayText(value){return String(value||'').replace(/학생[#\-\s](\d+)((?:\s*[·,/]\s*\d+)+)(으로|이나|이랑|은|는|이|가|을|를|과|와|로|나|랑)?/g,(match,firstNumber,remainingNumbers,particle)=>{const names=[Number(firstNumber),...(remainingNumbers.match(/\d+/g)||[]).map(Number)].map(teacherStudentName),lastName=names.at(-1)||'';return`${names.join('·')}${koreanParticleFor(lastName,particle)}`}).replace(/(?:학생[#\-\s](\d+)(?:번)?|(\d+)번(?:\s*학생)?)(?:\s+학생)?(?:\s*명)?(으로|이나|이랑|은|는|이|가|을|를|과|와|로|나|랑)?/g,(match,anonymousNumber,numberLabel,particle)=>{if(/^학생\s+\d+\s*명/.test(match))return match;const replacement=teacherStudentName(anonymousNumber||numberLabel);return`${replacement}${koreanParticleFor(replacement,particle)}`}).replace(/학생\s+학생/g,'학생').replace(/도움 요청가/g,'도움 요청이').replace(/도움 요청는/g,'도움 요청은').replace(/도움 요청를/g,'도움 요청을')}
function cleanAiEvidenceText(value){return aiTeacherDisplayText(String(value||'').replace(/^\[(계산 결과|학생 원문|친구 관찰)\]\s*/,''))}
function aiPrioritySummary(priority,includeNames=true){const immediate=priority.filter(item=>item.priority==='즉시 확인'),watch=priority.filter(item=>item.priority!=='즉시 확인'),named=(items,particle)=>{const names=items.map(item=>aiTeacherDisplayText(item.student)).join('·');return`${names}${koreanParticleFor(names,particle)}`};if(!priority.length)return'현재 응답에서 먼저 살펴볼 학생이 따로 없습니다.';if(!includeNames){const parts=[];if(immediate.length)parts.push(`바로 확인할 학생 ${immediate.length}명`);if(watch.length)parts.push(`대화와 관찰로 살펴볼 학생 ${watch.length}명`);return`${parts.join(' · ')}이 표시되었습니다.`}if(immediate.length&&watch.length)return`${named(immediate,'은')} 먼저 확인하고, ${named(watch,'은')} 대화와 관찰로 살펴보세요.`;if(immediate.length)return`${named(immediate,'은')} 먼저 확인해 주세요.`;return`${named(watch,'은')} 대화와 관찰로 살펴보세요.`}
function conciseAiSentence(value,max=80){const normalized=String(value||'').replace(/\s+/g,' ').trim(),first=normalized.match(/^.*?[.!?](?=\s|$)/)?.[0]||normalized;return first.length>max?`${first.slice(0,max-1).trim()}…`:first}
function removeObservationTiming(value){return String(value||'').replace(/(?:이번|다음|지난)\s*(?:주|달|학기)(?:\s*(?:동안|내내|중|안에|부터|까지))?/g,'').replace(/\s{2,}/g,' ').replace(/^[\s/·,]+|[\s/·,]+$/g,'').trim()}
function studentObservationSentence(point){if(!point)return'';return conciseAiSentence([point.context,point.behavior].map(removeObservationTiming).filter(Boolean).join(' / '),70)}
function aiEvidenceHTML(value,display){const text=String(value||''),match=text.match(/^\[(계산 결과|학생 원문|친구 관찰)\]\s*(.*)$/);return match?`<span class="ai-evidence-row"><b>${escapeHTML(match[1])}</b>${display(match[2])}</span>`:`<span class="ai-evidence-row"><b>기존 근거</b>${display(text)}</span>`}
function formatAnalysisTimestamp(value){const date=new Date(value||'');return Number.isNaN(date.getTime())?'시각 정보 없음':new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(date)}
function classResponseFlowData(){const current=latestByStudent(allResponses,selectedAnalysisMonth),enrollment=IeumEnrollment.summary(classSettings.students,current.keys(),selectedAnalysisMonth),total=enrollment.total,ratings=[],relationships=[];let conversationRequests=0,immediate=0,thisWeek=0;current.forEach(item=>{const payload=payloadOf(item),state=payload.studentState||{};Object.values(payload.selfRatings||{}).forEach(row=>{const score=Number(row?.score);if(score>0)ratings.push(score)});(payload.relationships||[]).forEach(row=>{const score=Number(row.score);if(score>0)relationships.push(score)});if(String(state.teacherWish||'').trim())conversationRequests++;if(payload.helpNow==='즉시')immediate++;if(payload.helpNow==='이번 주')thisWeek++});return{submitted:enrollment.submitted.length,total,rate:enrollment.rate,selfAverage:ratings.length?(ratings.reduce((sum,value)=>sum+value,0)/ratings.length).toFixed(1):'—',relationshipAverage:relationships.length?(relationships.reduce((sum,value)=>sum+value,0)/relationships.length).toFixed(1):'—',conversationRequests,immediate,thisWeek}}
function renderClassResponseFlowMetrics(){const target=$('#classResponseFlowMetrics');if(!target)return;const data=classResponseFlowData();target.innerHTML=`<article><span>설문 참여</span><strong>${data.submitted} / ${data.total}명</strong><small>${data.rate}% 참여</small></article><article><span>학교생활 자기평가</span><strong>${data.selfAverage} / 5</strong><small>선택한 달 평균</small></article><article><span>친구 관계 응답</span><strong>${data.relationshipAverage} / 5</strong><small>작성된 점수 평균</small></article><article><span>교사와 대화 희망</span><strong>${data.conversationRequests}명</strong><small>듣고 싶은 말을 작성함</small></article><article><span>도움 요청 선택</span><strong>즉시 ${data.immediate}명</strong><small>이번 주 ${data.thisWeek}명 · 선택한 달 응답 기준</small><small>AI 확인 대상과 별도</small></article>`}
function renderClassObservationPatterns(patterns){const target=$('#classObservationPatterns');if(!target)return;renderClassResponseFlowMetrics();const show=value=>escapeHTML(aiTeacherDisplayText(cleanAiEvidenceText(value))),items=patterns.slice(0,3);target.innerHTML=`<div class="class-flow-summary-head"><div><h4>이번 달 우리 반에서 보이는 흐름</h4><span>응답 원문·작성 학생 수 기준</span></div>${items.length?`<b>${items.length}가지</b>`:''}</div>${items.length?`<div class="class-observation-patterns">${items.map((item,index)=>`<article class="ai-result-card class-pattern-card"><span class="class-pattern-number" aria-hidden="true">${index+1}</span><div class="class-pattern-content"><h4>${show(conciseAiSentence(item.pattern))}</h4><div class="class-pattern-support"><section class="class-pattern-evidence"><strong>분석 근거</strong><p>${(item.evidence||[]).slice(0,2).map(value=>show(value)).join('<br>')}</p>${item.source_refs?.length?`<button type="button" class="text-button" data-ai-pattern-source="${index}">근거 원문</button>`:''}</section><section class="class-pattern-coaching"><strong>교실에서 살펴볼 점</strong>${IeumReportContent.renderSupportDirections(item,show,conciseAiSentence)}</section></div></div></article>`).join('')}</div>`:'<div class="ai-no-priority"><strong>이번 달에 공통으로 두드러진 흐름은 없습니다.</strong><p>현재 응답에서 여러 학생에게 공통으로 나타난 내용이 충분하지 않습니다.</p></div>'}`}
function renderAiAnalysis(result){renderAdditionalResponses(result.empty?{}:result.analysis||{});if(result.empty){currentAiAnalysis=null;currentAiRun={id:null,status:'active'};['#aiAnalysisMeta','#patternsAiMeta'].forEach(id=>$(id).textContent=result.validationBlocked?'근거 검증 보류':'저장된 분석 없음');$('#aiAnalysisContent').innerHTML=result.validationBlocked?'<p class="muted" role="status">저장 결과 표시 보류 · 현재 응답과의 근거 검증 필요 · 자동 재분석 없음</p>':'<p class="muted">저장된 분석이 없습니다. AI 새 분석을 눌러 생성해 주세요. 조회에는 비용이나 횟수가 차감되지 않습니다.</p>';renderClassObservationPatterns([]);if(result.validationBlocked)$('#classObservationPatterns').innerHTML='<p class="muted" role="status">저장 결과 표시 보류 · 현재 응답과의 근거 검증 필요</p>';return}const content=$('#aiAnalysisContent'),analysis=result.analysis||{},meta=result.meta||{},display=value=>escapeHTML(aiTeacherDisplayText(value));currentAiAnalysis=result;currentAiRun={id:meta.runId||result.id||null,status:meta.reviewStatus||'active'};const metaText=`마지막 분석 ${formatAnalysisTimestamp(meta.generatedAt)} · ${monthLabel(meta.month||selectedAnalysisMonth)} · ${meta.responseCount||0}명 · ${meta.cached?'저장 결과':'새 분석'} · ${meta.model||'AI'} · ${meta.analysisVersion||'버전 확인 불가'}`;$('#aiAnalysisMeta').textContent=metaText;$('#patternsAiMeta').textContent=metaText;const priority=(analysis.priority_students||[]).slice(0,3),patterns=analysis.class_patterns||[],summary=aiPrioritySummary(priority);renderClassObservationPatterns(patterns);content.innerHTML=`<section class="ai-overall-judgment"><p class="eyebrow">AI 학생 지원 요약</p><p class="ai-summary">${escapeHTML(summary)}</p></section><div class="ai-priority-heading"><h4>먼저 살펴볼 학생 ${priority.length}명</h4><span>담임 참고 · 교실에서 살펴볼 점 · 학생 코칭</span></div><div class="ai-priority-grid">${priority.length?priority.map((item,index)=>{const observation=studentObservationSentence((item.observation_points||[])[0]),question=(item.coaching_questions||item.teacher_checks||[])[0];return`<article class="ai-result-card teacher-action-card"><div class="ai-student-rank"><div><span class="tag ${item.priority==='즉시 확인'?'urgent':'watch'}">${display(item.priority)}</span><h4>${display(item.student)}</h4></div></div><div class="ai-student-support-grid"><section class="ai-attention-reason"><strong>담임 참고</strong><p>${display(conciseAiSentence(item.attention_reason||(item.possible_interpretations||[])[0]||'연결된 근거를 실제 상황에서 확인해 주세요.'))}</p>${(item.protective_factors||[]).length?`<p class="ai-protective-inline"><b>참고사항</b> ${display(conciseAiSentence(item.protective_factors[0],70))}</p>`:''}</section><section><strong>교실에서 살펴볼 점</strong><p>${display(observation||conciseAiSentence((item.teacher_checks||[])[0]||'교실에서 평소와 다른 모습을 살펴보세요.',70))}</p></section><section class="ai-coaching-questions"><strong>학생 코칭</strong><p>${display(conciseAiSentence(question||'요즘 학교생활에서 내가 도와주면 좋을 일이 있을까?',60))}</p></section></div><details class="ai-evidence-details"><summary>분석 근거 확인</summary><p class="muted">AI 해석을 확인할 때 관련 응답을 살펴보세요.</p><div class="ai-evidence-list">${(item.evidence||[]).map(value=>aiEvidenceHTML(value,display)).join('')}</div><button type="button" class="text-button" data-ai-source-index="${index}">관련 응답 보기</button></details></article>`}).join(''):'<div class="ai-no-priority"><strong>먼저 살펴볼 학생이 따로 없습니다</strong><p>현재 입력에서 의미 있는 복수 신호가 충분하지 않습니다.</p></div>'}</div>`}
async function runAiAnalysis(force=false){return aiAnalysisController.runAiAnalysis(force);}
async function ensureAiAnalysis(){return aiAnalysisController.ensureAiAnalysis();}
async function reviewAiAnalysis(status){if(!currentAiRun?.id){showToast('저장된 AI 분석 ID가 없습니다.');return}const note=await uiPrompt(status==='flagged'?'오류 판단 사유':'숨김 사유');if(!note?.trim())return;try{await teacherRpc('teacher_review_ai_analysis_auth',{p_class_id:classSettings.classId,p_run_id:currentAiRun.id,p_status:status,p_note:note.trim()});if(status==='hidden')$('#aiAnalysisPanel').hidden=true;else $('#aiAnalysisMeta').textContent+=' · 교사 오류 표시';showToast('AI 결과 검토 상태와 감사 로그를 저장했습니다.')}catch(error){showToast(`AI 검토 저장 실패: ${error.message}`)}}
const evidenceFieldLabels={helpNow:'도움 요청',studentState:{parentWish:'부모님께 바라는 점',worryDetail:'학교생활 고민',teacherWish:'선생님께 듣고 싶은 말'},peerObservations:{kind:{detail:'친절·존중 친구'},growth:{detail:'긍정적 변화 친구'},hurt:{detail:'상처를 준 말과 행동'},needsHelp:{detail:'도움이 필요한 친구'}},unresolved:{detail:'속상한 마음이 남은 관계'}};
function valueAtPath(object,path){return String(path).split('.').reduce((value,key)=>value?.[key],object)}
function labelAtPath(path){return String(path).split('.').reduce((value,key)=>value?.[key],evidenceFieldLabels)||path}
document.addEventListener('click',event=>{const button=event.target.closest('[data-ai-pattern-source]');if(button){const item=currentAiAnalysis?.analysis?.class_patterns?.[Number(button.dataset.aiPatternSource)];if(item)openAiSourceEvidence(item)}});
function openAiSourceEvidence(item){const refs=(item.source_refs||[]).map(ref=>{const [responseId,...fieldParts]=String(ref).split('|'),field=fieldParts.join('|'),response=allResponses.find(row=>String(row.id)===responseId);return response?{response,field,value:valueAtPath(payloadOf(response),field)}:null}).filter(row=>row?.value);$('#dialogTitle').textContent=`${item.student?aiTeacherDisplayText(item.student):'학급 흐름'} · 근거 원문`;$('#dialogContent').innerHTML=refs.length?refs.map(({response,field,value})=>`<article class="source-evidence"><div><span class="tag open">${escapeHTML(labelAtPath(field))}</span><small>${escapeHTML(monthLabel(monthOf(response)))} · ${new Date(response.submitted_at).toLocaleString('ko-KR')}</small></div><p>${escapeHTML(value)}</p></article>`).join('')+'<div class="notice warning"><span>!</span><p>선택형은 선택값, 서술형은 학생 작성 내용입니다. 다른 친구에 관한 진술은 작성 학생의 특성이나 확인된 사실이 아닙니다.</p></div>':'<p class="muted">연결된 원문을 찾지 못했습니다. 이전 형식의 저장 결과라면 새로 분석해 주세요.</p>';$('#evidenceDialog').showModal()}
function renderAdditionalResponses(analysis={}){
 const target=$('#additionalResponses');if(!target)return;
 const review=IeumSurveyReview.coverage(allResponses,selectedAnalysisMonth,analysis),groups=new Map();
 for(const item of review.additional){if(!groups.has(item.number))groups.set(item.number,[]);groups.get(item.number).push(item)}
 const focus=new Set(['helpNow','studentState.worryDetail','studentState.parentWish','peerObservations.hurt.detail','peerObservations.needsHelp.detail','unresolved.detail']);
 const fieldHTML=item=>`<article class="source-evidence"><strong>${escapeHTML(item.label)}</strong><p>${escapeHTML(item.value)}</p>${item.peer?'<small>다른 친구에 관한 진술 · 대상·상황 확인</small>':''}${item.sourceType?`<small>학생 선택: ${escapeHTML(item.sourceType)} · ${escapeHTML(item.frequency||'')} · 계속 여부 ${item.ongoing===true?'예':item.ongoing===false?'아니요':'미응답'}</small>`:''}</article>`;
 target.innerHTML=`<section class="additional-review"><h4>추가 확인 응답 <span>${groups.size}명</span></h4><p class="muted">${escapeHTML(monthLabel(selectedAnalysisMonth))} · AI 요약에 연결되지 않은 원문 · 위험 판정 아님</p><p class="muted">검토 대상 ${review.checked}건 · 요약 연결 ${review.covered}건 · 추가 확인 ${review.additional.length}건</p>${[...groups].map(([number,items])=>{const main=items.filter(item=>focus.has(item.field)),other=items.filter(item=>!focus.has(item.field));return`<details class="ai-evidence-details"><summary>${escapeHTML(aiTeacherDisplayText('학생-'+number))} · ${main.length?'도움·관계·바람 문항 '+main.length+'건':'기타 서술 확인'} · 총 ${items.length}건</summary>${main.map(fieldHTML).join('')}${other.length?`<details><summary>자기평가·긍정 문항·교사에게 바라는 말 ${other.length}건</summary>${other.map(fieldHTML).join('')}</details>`:''}</details>`}).join('')||'<p class="muted">추가 표시 원문 없음 · 어려움 없음 판정 아님</p>'}</section>`;
}
function attachAiSourceButtons(){const priority=currentAiAnalysis?.analysis?.priority_students||[];$$('#aiAnalysisContent .ai-result-card').slice(0,priority.length).forEach((card,index)=>{if(card.querySelector('[data-ai-source-index]'))return;const button=document.createElement('button');button.type='button';button.className='secondary-button ai-source-button';button.dataset.aiSourceIndex=String(index);button.textContent='근거 원문 보기';card.append(button)})}
new MutationObserver(attachAiSourceButtons).observe($('#aiAnalysisContent'),{childList:true,subtree:true});
document.addEventListener('click',event=>{const sourceButton=event.target.closest('[data-ai-source-index]');if(sourceButton)openAiSourceEvidence(currentAiAnalysis.analysis.priority_students[Number(sourceButton.dataset.aiSourceIndex)])});
function renderStudents(){renderResponses([])}
