function updateRelationshipMonthSelector(){const selector=$('#relationshipAnalysisMonth'),months=availableRelationshipMonths(),displayMonths=[...months].reverse(),aiSelected=$('#relationTabs [data-relation-tab="ai"]')?.classList.contains('active');if(!selector)return;if(!months.includes(selectedRelationshipMonth))selectedRelationshipMonth=months.at(-1)||'';const rangeOption=aiSelected?'':`<option value="all" ${relationshipMapMode==='cumulative'?'selected':''}>여러 달 함께 보기</option>`;selector.innerHTML=rangeOption+displayMonths.map(month=>`<option value="${month}" ${relationshipMapMode==='monthly'&&month===selectedRelationshipMonth?'selected':''}>${monthLabel(month)}</option>`).join('');selector.value=aiSelected?selectedRelationshipMonth:(relationshipMapMode==='cumulative'?'all':selectedRelationshipMonth);selector.disabled=!months.length}
function relationshipMapState(){const months=availableRelationshipMonths();if(!months.includes(selectedRelationshipMonth))selectedRelationshipMonth=months.at(-1)||'';const source=relationshipMapMode==='cumulative'?allResponses:allResponses.filter(item=>monthOf(item)===selectedRelationshipMonth),analysis=buildCumulativeRelationshipAnalysis(source),monthIndex=months.indexOf(selectedRelationshipMonth),previousMonth=monthIndex>0?months[monthIndex-1]:'',previous=previousMonth?buildCumulativeRelationshipAnalysis(allResponses.filter(item=>monthOf(item)===previousMonth)):null;return{months,analysis,previousMonth,previous}}

function separateRelationshipPositions(positions,width,height){const entries=[...positions.entries()],minX=132,minY=60,paddingX=68,paddingY=34;for(let pass=0;pass<120;pass++){let moved=false;for(let i=0;i<entries.length;i++)for(let j=i+1;j<entries.length;j++){const [numberA,a]=entries[i],[numberB,b]=entries[j],dx=b.x-a.x,dy=b.y-a.y,overlapX=minX-Math.abs(dx),overlapY=minY-Math.abs(dy);if(overlapX<=0||overlapY<=0)continue;moved=true;if(overlapX/minX<overlapY/minY){const direction=dx===0?(numberA<numberB?1:-1):Math.sign(dx),shift=overlapX/2+.6;a.x-=direction*shift;b.x+=direction*shift}else{const direction=dy===0?(numberA<numberB?1:-1):Math.sign(dy),shift=overlapY/2+.6;a.y-=direction*shift;b.y+=direction*shift}a.x=Math.max(paddingX,Math.min(width-paddingX,a.x));b.x=Math.max(paddingX,Math.min(width-paddingX,b.x));a.y=Math.max(paddingY,Math.min(height-paddingY,a.y));b.y=Math.max(paddingY,Math.min(height-paddingY,b.y))}if(!moved)break}return positions}

function renderRelationshipsV2(){
  const content=$('#relationContent'),confidence=$('#relationConfidence'),preview=$('#relationPreview');if(!content||!confidence)return;
  const hasResponses=allResponses.length>0,tabs=$('#relationTabs');if(tabs&&!tabs.dataset.initialized){tabs.dataset.initialized='true';setRelationshipTab('example')}
  const mapState=relationshipMapState(),analysis=mapState.analysis,rate=analysis.total?Math.round(analysis.submitted/analysis.total*100):0,relationRate=analysis.total?Math.round(analysis.relationCount/analysis.total*100):0;updateRelationshipMonthSelector();
  if(!hasResponses){const sampleLegend=preview?.querySelector('.legend');if(sampleLegend){sampleLegend.className='relation-legend';sampleLegend.innerHTML='<span><i class="solid-line"></i>실선 · 서로 4~5점을 준 관계</span><span><i class="dashed-line"></i>점선 · 서로 다른 학생 묶음을 잇는 관계</span><span><i class="group-colors"></i>색상 · 높은 점수를 주고받은 학생들</span><span><i class="neutral-color"></i>회색 · 표시된 연결이 아직 적음</span>'}confidence.className='confidence';confidence.textContent='등록 자료 0건 · 표시 방법';content.innerHTML='<div class="notice safe"><span>ⓘ</span><div><strong>아직 등록된 설문 자료가 없습니다.</strong><p>아래 화면은 관계 지도 표시 방법의 예시이며 실제 학생 분석 결과가 아닙니다.</p></div></div>';return}
  confidence.className=`confidence ${analysis.ready?'good':''}`;confidence.textContent=analysis.ready?`${relationshipMapMode==='monthly'?monthLabel(selectedRelationshipMonth):`${analysis.months.length}개월 누적`} · 설문 참여율 ${rate}% · 친구 관계 응답률 ${relationRate}%`:`${relationshipMapMode==='monthly'?monthLabel(selectedRelationshipMonth):'누적'} 관계 응답이 더 필요해요 · 설문 참여율 ${rate}% · 친구 관계 응답률 ${relationRate}%`;
  if(!analysis.ready){content.innerHTML=`<div class="notice warning relation-warning"><span>!</span><div><strong>${relationshipMapMode==='monthly'?`${monthLabel(selectedRelationshipMonth)} 관계 지도를 표시하려면 응답이 더 필요합니다.`:'누적 관계 흐름을 표시하려면 응답이 더 필요합니다.'}</strong><p>선택 범위의 설문 참여율과 친구 관계 응답률이 각각 80% 이상일 때 관계 지도를 표시합니다. 결석·미제출은 0점으로 계산하지 않습니다.</p></div></div>`;return}
  const width=1100,height=640,positions=new Map(),palette=['#d9edf4','#e8e0f4','#dff3e9','#fff0d8','#f7dfe3'],groupCount=analysis.groups.length,centerX=width/2,centerY=height/2-12,centerRadius=groupCount<=1?0:groupCount===2?250:groupCount===3?220:Math.min(245,145+groupCount*18);
  analysis.groups.forEach((group,index)=>{const centerAngle=groupCount===2?(index===0?Math.PI:0):-Math.PI/2+2*Math.PI*index/groupCount,gx=centerX+Math.cos(centerAngle)*centerRadius,gy=centerY+Math.sin(centerAngle)*centerRadius*.72,nodeRadius=Math.min(112,Math.max(68,48+group.length*8));group.forEach((number,nodeIndex)=>{const angle=-Math.PI/2+2*Math.PI*nodeIndex/group.length;positions.set(number,{x:gx+Math.cos(angle)*nodeRadius,y:gy+Math.sin(angle)*nodeRadius,group:index})})});
  const unplaced=analysis.students.filter(student=>!positions.has(Number(student.number))),unplacedRadiusX=groupCount?width*.43:width*.34,unplacedRadiusY=groupCount?height*.41:height*.33;unplaced.forEach((student,index)=>{const angle=-Math.PI/2+2*Math.PI*index/Math.max(unplaced.length,1);positions.set(Number(student.number),{x:centerX+Math.cos(angle)*unplacedRadiusX,y:centerY+Math.sin(angle)*unplacedRadiusY,group:-1})});
  separateRelationshipPositions(positions,width,height);
  const edgeKey=edge=>[edge.a,edge.b].sort((a,b)=>a-b).join(':'),newKeys=new Set((relationshipChanges()?.total.new||[]).map(edgeKey));
  const lines=analysis.mutual.map(edge=>{const a=positions.get(edge.a),b=positions.get(edge.b),changeClass=relationshipMapMode==='monthly'&&newKeys.has(edgeKey(edge))?'relationship-new':'';return`<line data-relation-edge data-a="${edge.a}" data-b="${edge.b}" class="${a.group!==b.group?'bridge':''} ${changeClass}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/>`}).join('');
  const nodes=analysis.students.map(student=>{const number=Number(student.number),pos=positions.get(number),fill=pos.group>=0?palette[pos.group%palette.length]:'#eef1f3';return`<g transform="translate(${pos.x.toFixed(1)} ${pos.y.toFixed(1)})" data-student-node data-number="${number}"><rect x="-60" y="-22" width="120" height="44" rx="14" style="fill:${fill}"/><text>${escapeHTML(student.name)}</text><title>${escapeHTML(student.name)}</title></g>`}).join('');
  const focusOptions=analysis.students.map(student=>`<option value="${Number(student.number)}">${escapeHTML(student.name)}</option>`).join('');
  const comparison=relationshipChangeHTML();
  content.innerHTML=`<div class="relation-dashboard actual-relations">${comparison}<div class="panel network-panel"><div class="panel-head"><div><p class="eyebrow">${relationshipMapMode==='monthly'?`${monthLabel(selectedRelationshipMonth)} 관계 응답`:`전체 ${analysis.months.length}개월 관계 응답`}</p><h3>${relationshipMapMode==='monthly'?'월별 관계 지도':'누적 관계 지도'}</h3></div><div class="relation-tools"><label>학생 선택해 보기<select id="relationStudentFocus"><option value="">전체 학생</option>${focusOptions}</select></label></div></div><div class="network-fixed-frame"><div class="network show-names" id="network" aria-label="${relationshipMapMode==='monthly'?'월별':'누적'} 우리 반 관계 지도"><svg width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img"><g class="links">${lines}</g><g class="nodes">${nodes}</g></svg><div class="relation-legend"><span><i class="solid-line"></i>실선 · 서로 4~5점을 준 관계</span><span><i class="dashed-line"></i>점선 · 서로 다른 학생 묶음을 잇는 관계</span><span><i class="group-colors"></i>색상 · 높은 점수를 주고받은 학생들</span><span><i class="neutral-color"></i>회색 · 표시된 연결이 아직 적음</span></div></div></div><p class="muted">${relationshipMapMode==='monthly'?'선택한 달의 학생별 최신 응답만 사용합니다. 이전 달에 보였던 연결이 없더라도 관계가 끊어졌다는 뜻은 아닙니다.':'전체 월의 실제 응답만 평균하며 결석·미제출 월은 평균에서 제외합니다.'}</p></div></div>`;
  const legend=content.querySelector('.relation-legend');if(legend)legend.setAttribute('aria-label','우리 반 관계 지도 범례');
  const networkNote=content.querySelector('.network-panel>.muted');if(networkNote)networkNote.textContent=relationshipMapMode==='monthly'?'1100×640 기준의 반응형 캔버스입니다. 선택한 달의 학생별 최신 응답만 사용하며, 확인되지 않은 연결을 관계 단절로 해석하지 않습니다.':'1100×640 기준의 반응형 캔버스입니다. 전체 월의 실제 응답만 평균하며 결석·미제출 월은 평균에서 제외합니다.';
  confidence.textContent=relationshipMapMode==='monthly'?`${monthLabel(selectedRelationshipMonth)} 친구 관계 응답 반영`:`${analysis.months.length}개월 친구 관계 응답 누적 참고`;
  content.insertAdjacentHTML('beforeend',relationshipEvidenceHTML(mapState));
  content.querySelectorAll('.relation-legend span').forEach(span=>{if(span.textContent.startsWith('색상'))span.lastChild.textContent='색상 · 높은 점수로 이어진 연결 묶음';if(span.textContent.startsWith('회색'))span.lastChild.textContent='회색 · 색상 묶음에 포함되지 않음'});
}

function relationshipChanges(){
  const month=relationshipMapMode==='cumulative'?availableRelationshipMonths().at(-1):selectedRelationshipMonth;
  return IeumRelationshipChanges.compare(allResponses,classSettings.students,month,IeumRelationshipData);
}
function relationshipBriefHTML(month,number,cumulative=false){
  if(!/^\d{4}-\d{2}$/.test(month||''))return '';
  const rows=allResponses.filter(row=>cumulative?monthOf(row)<=month:monthOf(row)===month);
  const roster=relationshipRoster(rows),quality=IeumRelationshipEvidence.build(rows,roster,IeumAnalysisCore);
  const comparison=IeumRelationshipChanges.compare(allResponses,classSettings.students,month,IeumRelationshipData);
  const brief=IeumRelationshipEvidence.overview(quality,comparison,number);
  const scope=cumulative?`${monthLabel(month)}까지 누적 · 같은 달 응답끼리 확인`:`${monthLabel(month)} 응답 기준`;
  return `<section class="relationship-brief" aria-label="관계 응답 요약"><p class="relationship-brief-scope">${escapeHTML(scope)} · 변화 비교 ${escapeHTML(comparison.previousMonth)} → ${escapeHTML(month)}</p><div class="relationship-brief-grid">${[['확인된 연결',brief.confirmed],['이전과 달라진 점',brief.change],['해석에 필요한 자료',brief.needs]].map(([title,body])=>`<article><h4>${title}</h4><p>${escapeHTML(body)}</p></article>`).join('')}</div><p class="relationship-brief-note">‘연결’은 같은 달 서로 4점 이상인 응답이며 친구 수나 친밀도를 확정하지 않습니다. 미응답은 관계 없음이 아닙니다.</p></section>`;
}
function relationshipChangeHTML(number){
  const result=relationshipChanges();if(!result)return '';
  const summary=number?result.byStudent.get(number):result.total;if(!summary)return '';
  const describe=list=>number?(list.map(pair=>{const other=pair.a===number?pair.b:pair.a;return escapeHTML(classSettings.students.find(student=>Number(student.number)===other)?.name||`${other}번`)}).join(' · ')||'없음'):`${list.length}쌍`;
  return `${relationshipBriefHTML(result.month,number,relationshipMapMode==='cumulative')}<details class="panel relationship-change-card"><summary>관계 변화의 세부 근거</summary><h4>최근 관계 응답 변화 · ${escapeHTML(result.previousMonth)} → ${escapeHTML(result.month)}</h4>${!result.hasPrevious?'<p>직전 달 자료가 없어 비교를 보류합니다. 이전의 다른 달로 건너뛰어 비교하지 않습니다.</p>':`<p>두 달 모두 양방향 응답과 학생 신원이 확인된 ${summary.comparable}${number?'명':'쌍'}만 비교합니다.</p><ul><li>새로 높은 점수 기준에 해당: ${describe(summary.new)}</li><li>두 달 연속 높은 점수 기준에 해당: ${describe(summary.continued)}</li><li>이번 달 높은 점수 기준 미충족: ${describe(summary.below)}</li></ul>`}<p>비교 보류 · 응답 부족 ${summary.missing.length}${number?'명':'쌍'} · 학생 식별 확인 필요 ${summary.identity.length}${number?'명':'쌍'} · 전출 기간 ${summary.enrollment.length}${number?'명':'쌍'}</p><p class="muted">높은 점수 기준은 서로 4점 이상입니다. 기준 미충족은 관계가 끊어졌다는 뜻은 아닙니다. 결석·미참여 이유는 추정하지 않습니다. 전출한 달부터 관계 변화 비교를 보류합니다. 전입일은 아직 반영하지 않습니다.</p></details>`;
}
function relationshipEvidenceHTML(mapState){
  const analysis=mapState.analysis;
  const groups=IeumRelationshipEvidence.groups(analysis),names=numbers=>numbers.map(number=>classSettings.students.find(student=>Number(student.number)===number)?.name||`${number}번`).join(' · ');
  const groupHTML=groups.map((group,index)=>`<li><strong>연결 묶음 ${index+1}</strong> · ${escapeHTML(names(group.members))}<br>내부 강한 연결 ${group.links}/${group.possible}쌍 (${Math.round(group.density*100)}%)</li>`).join('');
  return`<section class="panel relationship-evidence" aria-label="관계 관측 근거"><h3>관계 관측 근거</h3><p class="muted">응답률은 자료량 안내이지 정확도 인증이 아닙니다. 결석·미응답은 0점이나 관계 없음으로 계산하지 않습니다.</p><div id="relationshipStudentEvidence"><p>위에서 학생을 선택하면 받은 응답 수와 관계별 관측 기간을 볼 수 있습니다.</p></div><details><summary>색상 묶음의 구성 근거 (${groups.length}개)</summary><p>서로 누적 평균 4.5점 이상인 연결을 따라 묶었습니다. 월별 화면은 해당 달 점수를 사용합니다. 구성원 모두가 서로 친하거나 고정된 집단이라는 뜻은 아닙니다. 기준점을 바꾸면 묶음도 달라질 수 있습니다.</p>${groupHTML?`<ul>${groupHTML}</ul>`:'<p>표시 기준에 해당하는 연결 묶음이 없습니다.</p>'}</details></section>`;
}
function renderRelationshipStudentEvidence(number){
  const container=$('#relationshipStudentEvidence');if(!container)return;
  if(!number){container.innerHTML='<p>위에서 학생을 선택하면 받은 응답 수와 관계별 관측 기간을 볼 수 있습니다.</p>';return}
  const rows=relationshipMapMode==='monthly'?allResponses.filter(item=>monthOf(item)===selectedRelationshipMonth):allResponses,quality=IeumRelationshipEvidence.build(rows,relationshipRoster(rows),IeumAnalysisCore),summary=quality.byStudent.get(number),analysis=relationshipMapState().analysis;
  if(!summary)return;
  const connections=analysis.mutual.filter(edge=>edge.a===number||edge.b===number).length,pairs=quality.pairs.filter(pair=>pair.a===number||pair.b===number),name=classSettings.students.find(student=>Number(student.number)===number)?.name||'';
  container.innerHTML=`<h4>${escapeHTML(name)} · 응답 자료</h4><p>받은 응답 <strong>${summary.incomingResponses}건 · ${summary.incomingPeers}/${summary.possible}명</strong> · 관측 ${summary.months.length}개월<br>같은 달 양방향 관측 ${summary.bothPeers}/${summary.possible}명 · 평균 기준 연결 ${connections}명</p><p>${IeumRelationshipEvidence.description(summary,connections)}</p><p class="muted">양방향 관측 상대가 80% 미만이면 연결 수 해석을 보류하는 운영 기준입니다. 연구로 검증된 신뢰도 기준은 아닙니다.</p><details><summary>관계별 응답과 관측 월 보기</summary><div class="relationship-evidence-scroll"><table><caption>방향별 평균은 각자의 실제 응답만 사용합니다. 누적 평균 연결과 같은 달 상호 관측은 다릅니다.</caption><thead><tr><th scope="col">상대 학생</th><th scope="col">내가 준 응답</th><th scope="col">받은 응답</th><th scope="col">관측 월</th><th scope="col">같은 달 양방향</th><th scope="col">상호 관측 해석</th></tr></thead><tbody>${pairs.map(pair=>{const forward=pair.a===number,other=forward?pair.b:pair.a,student=classSettings.students.find(item=>Number(item.number)===other),format=(average,count)=>count?`${average.toFixed(2)}점 · ${count}건`:'미관측';return`<tr><th scope="row">${escapeHTML(student?.name||`${other}번`)}</th><td>${format(forward?pair.abAverage:pair.baAverage,forward?pair.abCount:pair.baCount)}</td><td>${format(forward?pair.baAverage:pair.abAverage,forward?pair.baCount:pair.abCount)}</td><td>${pair.months.join(', ')||'미관측'}</td><td>${pair.commonMonths.length}개월</td><td>${escapeHTML(IeumRelationshipEvidence.pairDescription(pair))}</td></tr>`}).join('')}</tbody></table></div></details>`;
}
document.addEventListener('change',event=>{if(event.target.id==='relationStudentFocus'){renderRelationshipStudentEvidence(Number(event.target.value));if(Number(event.target.value))$('#relationshipStudentEvidence')?.insertAdjacentHTML('afterbegin',relationshipChangeHTML(Number(event.target.value)))}});
document.addEventListener('click',event=>{const node=event.target.closest('[data-student-node]'),select=$('#relationStudentFocus');if(node&&select){select.value=node.dataset.number;select.dispatchEvent(new Event('change',{bubbles:true}))}});

function setRelationshipTab(tab){
  const actual=$('#relationActualPanel'),example=$('#relationPreview'),ai=$('#relationAiPanel'),tabs=$('#relationTabs');if(!actual||!example||!ai||!tabs)return;
  example.hidden=tab!=='example';actual.hidden=tab!=='actual';ai.hidden=tab!=='ai';
  tabs.querySelectorAll('[data-relation-tab]').forEach(button=>{const selected=button.dataset.relationTab===tab;button.classList.toggle('active',selected);button.setAttribute('aria-selected',String(selected))});
  updateRelationshipMonthSelector();
}

document.addEventListener('click',event=>{const button=event.target.closest('[data-relation-tab]');if(button){$('#relationTabs').dataset.userSelected='true';setRelationshipTab(button.dataset.relationTab)}});
document.addEventListener('change',event=>{if(event.target.id==='relationshipAnalysisMonth'){if(event.target.value==='all')relationshipMapMode='cumulative';else{selectedRelationshipMonth=event.target.value;relationshipMapMode='monthly'}renderRelationshipsV2();renderRelationshipActions()}});

function renderRelationshipActions(){
  const container=$('#relationshipActions');if(!container)return;const analysis=buildCumulativeRelationshipAnalysis(allResponses);if(!analysis.ready){container.innerHTML='';return}updateRelationshipMonthSelector();
  container.innerHTML=`<section class="panel ai-analysis-panel relationship-actions class-relationship-reading"><div class="panel-head relationship-ai-head"><h3>AI 관계 코칭</h3><div class="ai-review-actions"><span class="confidence" id="relationshipAiMeta">마지막 분석 확인 전</span><button type="button" class="text-button" id="runRelationshipAi">저장 결과 조회</button><button type="button" class="text-button" id="rerunRelationshipAi">AI 새 분석</button></div></div><div id="relationshipAiContent"><p class="muted">선택한 달의 저장 결과를 불러오거나 AI 새 분석을 실행해 주세요.</p></div><p class="muted">관계 응답은 실제 친밀도나 고정된 친구 집단을 확정하는 결과가 아닙니다. 담임 관찰과 학생 대화로 함께 확인해 주세요.</p></section>`;
}

function relationshipAnalysisMonth(){const months=availableRelationshipMonths();if(!months.includes(selectedRelationshipMonth))selectedRelationshipMonth=months.at(-1)||'';return selectedRelationshipMonth||new Date().toISOString().slice(0,7)}
function relationshipAnalysisHasFormerStudents(analysis){return[...JSON.stringify(analysis||{}).matchAll(/(?:학생[#\-\s](\d+)(?:번)?|(\d+)번(?:\s*학생)?)/g)].some(match=>{const number=Number(match[1]||match[2]);return!classSettings.students.some(student=>Number(student.number)===number)})}
function renderRelationshipAiAnalysis(result){if(result.empty){currentRelationshipAiAnalysis=null;$('#relationshipAiMeta').textContent='저장된 분석 없음';$('#relationshipAiContent').innerHTML='<p class="muted">저장된 분석이 없습니다. AI 새 분석을 눌러 생성해 주세요. 조회에는 비용이나 횟수가 차감되지 않습니다.</p>';return}const analysis=result.analysis||{},meta=result.meta||{},display=value=>escapeHTML(aiTeacherDisplayText(value)),insights=(analysis.insights||[]).slice(0,2),content=$('#relationshipAiContent'),hasFormerStudents=relationshipAnalysisHasFormerStudents(analysis),upgradeNotice=meta.upgradeRecommended?'<section class="relationship-ai-upgrade" role="status"><strong>이전 형식으로 저장된 결과입니다.</strong><p>선택한 달 기준으로 다시 보려면 AI 새 분석을 실행해 주세요.</p></section>':hasFormerStudents?'<section class="relationship-ai-upgrade" role="status"><strong>이전 명단 학생이 포함된 저장 결과입니다.</strong><p>현재 명단을 기준으로 다시 살펴보려면 AI 새 분석을 실행해 주세요.</p></section>':'';currentRelationshipAiAnalysis=result;if(!content)return;$('#relationshipAiMeta').textContent=`마지막 분석 ${formatAnalysisTimestamp(meta.generatedAt)} · ${monthLabel(meta.month||relationshipAnalysisMonth())} · 관계 응답 ${meta.responseCount||0}건 · ${meta.cached?'저장 결과':'새 분석'} · ${meta.analysisVersion||'버전 확인 불가'}`;content.innerHTML=`${upgradeNotice}<section class="relationship-ai-summary"><strong>우리 반 관계 요약</strong><p>${display(conciseAiSentence(analysis.summary||'관계 코칭 요약이 없습니다.',90))}</p></section><div class="relationship-ai-reading">${insights.map((item,index)=>{const coaching=item.class_coaching||item.operation_method||item.coaching_direction||'이번 활동에서는 평소와 다른 친구의 의견도 한 번 들어 보자.',timeframe=item.timeframe||(meta.upgradeRecommended?'이전 저장 결과':'선택한 달의 관계 모습');return`<article class="relationship-coaching-card"><div class="relationship-insight-heading"><span>${display(timeframe)}</span></div><section><strong>관계에서 보이는 모습</strong><p>${display(conciseAiSentence(item.observation||item.title||`관계 모습 ${index+1}`,90))}</p></section><section class="relationship-teacher-check"><strong>교실에서 살펴볼 점</strong><p>${display(conciseAiSentence(item.teacher_check,60))}</p></section><section class="class-reading-coaching"><strong>학급 코칭</strong><p>${display(conciseAiSentence(coaching,60))}</p></section><details><summary>분석 근거</summary><p>${(item.evidence||[]).slice(0,2).map(value=>display(cleanAiEvidenceText(value))).join('<br>')}</p></details></article>`}).join('')}</div>`}
async function runRelationshipAiAnalysis(force=false){return aiAnalysisController.runRelationshipAiAnalysis(force);}
document.addEventListener('click',event=>{if(event.target.id==='runRelationshipAi')runRelationshipAiAnalysis(false);if(event.target.id==='rerunRelationshipAi')runRelationshipAiAnalysis(true)});

// 관계 분석은 특정 월이 아니라 저장된 전체 월의 실제 응답을 누적 평균한다.
// 미제출 월(결석 포함)은 0점으로 보지 않고 평균의 분모에서 제외한다.
function relationshipRoster(responses){const months=[...new Set(responses.map(monthOf))];return classSettings.students.filter(student=>!months.length||months.some(month=>IeumEnrollment.status(student,month)!=='transferred'))}
function buildCumulativeRelationshipAnalysis(responses){const students=relationshipRoster(responses);return IeumRelationshipCore.build(IeumRelationshipData.normalizeResponses(responses,students),students,IeumAnalysisCore)}
